package com.edward.galleryflow;
import android.content.*;import android.net.Uri;import android.provider.*;import org.json.*;import java.io.*;import java.util.*;import java.security.*;
/** Persistent operation journal. SAF originals are backed up before removal. */
final class FileActions{
 final Context c;final android.content.SharedPreferences p;final File dir;static final long RETENTION=30L*86400000;
 FileActions(Context c){this.c=c.getApplicationContext();p=c.getSharedPreferences("file-actions",0);dir=new File(c.getFilesDir(),"trash");dir.mkdirs();}
 synchronized List<JSONObject> records(){List<JSONObject> out=new ArrayList<>();try{JSONArray a=new JSONArray(p.getString("records","[]"));for(int n=0;n<a.length();n++)out.add(a.getJSONObject(n));}catch(Exception ignored){}return out;}
 synchronized void save(List<JSONObject> rows){JSONArray a=new JSONArray();for(JSONObject o:rows)a.put(o);p.edit().putString("records",a.toString()).commit();}
 synchronized void add(JSONObject o){List<JSONObject> rows=records();rows.add(o);save(rows);}
 synchronized void remove(JSONObject o){List<JSONObject> rows=records();rows.removeIf(r->r.optString("id").equals(o.optString("id")));save(rows);}
 JSONObject record(MediaRepository.Item i,String type,String batch)throws Exception{return new JSONObject().put("id",UUID.randomUUID().toString()).put("type",type).put("batch",batch).put("uri",i.uri.toString()).put("name",i.name).put("mime",i.mime).put("key",LockStore.itemKey(i)).put("time",System.currentTimeMillis()).put("expires",System.currentTimeMillis()+retentionMillis()).put("size",i.size).put("date",i.date).put("ratio",i.ratio).put("path",i.path).put("video",i.video);}
 List<JSONObject> latest(){List<JSONObject> rows=records();if(rows.isEmpty())return rows;String batch=rows.get(rows.size()-1).optString("batch");rows.removeIf(o->!o.optString("batch").equals(batch));return rows;}
 List<JSONObject> trash(){List<JSONObject> rows=records();rows.removeIf(o->o.optString("type").equals("copy")||o.optString("type").equals("expired"));Iterator<JSONObject> it=rows.iterator();while(it.hasNext()){JSONObject o=it.next();if(o.optString("type").equals("native")&&android.os.Build.VERSION.SDK_INT>=30){android.os.Bundle args=new android.os.Bundle();args.putInt(MediaStore.QUERY_ARG_MATCH_TRASHED,MediaStore.MATCH_INCLUDE);try(android.database.Cursor cursor=c.getContentResolver().query(Uri.parse(o.optString("uri")),new String[]{"is_trashed","date_expires"},args,null)){if(cursor!=null){if(!cursor.moveToFirst()){markExpired(o);it.remove();}else if(cursor.getInt(0)==0)it.remove();else {long system=cursor.getLong(1)*1000;long selected=o.optLong("expires",o.optLong("time")+RETENTION);o.put("expires",system>0?Math.min(system,selected):selected);o.put("systemExpires",system);}}}catch(Exception ignored){}}}return rows;}
 void nativeTrash(MediaRepository.Item i,String batch)throws Exception{add(record(i,"native",batch));}
 void trashDocument(MediaRepository.Item i,String batch)throws Exception{
  if(!i.document)throw new IOException("Open this folder through Explorer and grant write access to use Trash on Android 10.");
  String id=DocumentsContract.getDocumentId(i.uri);int slash=id.lastIndexOf('/');if(slash<0)throw new IOException("Cannot determine original folder; file was kept.");Uri parent=DocumentsContract.buildDocumentUriUsingTree(i.uri,id.substring(0,slash));
  JSONObject o=record(i,"local",batch).put("parent",parent.toString());File backup=new File(dir,o.getString("id"));
  try(InputStream in=c.getContentResolver().openInputStream(i.uri);FileOutputStream out=new FileOutputStream(backup)){if(in==null)throw new IOException("Cannot read original");transfer(in,out);out.getFD().sync();}catch(Exception e){backup.delete();throw e;}
  o.put("backup",backup.getName());add(o);
  try{if(!DocumentsContract.deleteDocument(c.getContentResolver(),i.uri))throw new IOException("Provider refused removal");}catch(Exception e){remove(o);backup.delete();throw e;}
 }
 JSONObject copy(MediaRepository.Item i,Uri parent,String batch)throws Exception{
  Uri target=DocumentsContract.createDocument(c.getContentResolver(),parent,i.mime,i.name);if(target==null)throw new IOException("Cannot create destination");
  try{try(InputStream in=c.getContentResolver().openInputStream(i.uri);OutputStream out=c.getContentResolver().openOutputStream(target)){if(in==null||out==null)throw new IOException("Cannot open file");transfer(in,out);}JSONObject o=record(i,"copy",batch).put("dest",target.toString()).put("digest",digest(target));add(o);return o;}catch(Exception e){try{DocumentsContract.deleteDocument(c.getContentResolver(),target);}catch(Exception ignored){}throw e;}
 }
 void undoLocal(JSONObject o)throws Exception{
  if(o.optString("type").equals("expired"))throw new IOException("Original has expired or was permanently deleted; copies were kept.");
  if(o.optString("type").equals("copy")){Uri u=Uri.parse(o.getString("dest"));if(!digest(u).equals(o.getString("digest")))throw new IOException("Copied file changed; it was kept to protect your edits.");if(!DocumentsContract.deleteDocument(c.getContentResolver(),u))throw new IOException("Cannot remove copied file");remove(o);return;}
  File backup=new File(dir,o.getString("backup"));if(!backup.isFile())throw new IOException("Trash file is unavailable");Uri target=DocumentsContract.createDocument(c.getContentResolver(),Uri.parse(o.getString("parent")),o.getString("mime"),o.getString("name"));if(target==null)throw new IOException("Original folder is unavailable");
  try(InputStream in=new FileInputStream(backup);OutputStream out=c.getContentResolver().openOutputStream(target)){if(out==null)throw new IOException("Cannot restore file");transfer(in,out);}catch(Exception e){try{DocumentsContract.deleteDocument(c.getContentResolver(),target);}catch(Exception ignored){}throw e;}remove(o);backup.delete();
 }
 void purge(JSONObject o)throws Exception{if(o.optString("type").equals("native"))throw new IOException("Requires Android confirmation");File f=new File(dir,o.getString("backup"));if(f.exists()&&!f.delete())throw new IOException("Cannot remove trash file");markExpired(o);}
 long retentionMillis(){return GalleryFormatting.retentionMillis(new AppSettings(c).num("trashDays",30));}
 void expire(){for(JSONObject o:trash())if(System.currentTimeMillis()>=o.optLong("expires",o.optLong("time")+RETENTION))try{if(o.optString("type").equals("native")){if(c.getContentResolver().delete(Uri.parse(o.optString("uri")),null,null)>0)markExpired(o);}else purge(o);}catch(Exception ignored){/* Android may require a user-approved delete; keep it restorable. */}}
 List<MediaRepository.Item> trashItems(LockStore locks,boolean admin){List<MediaRepository.Item> out=new ArrayList<>();for(JSONObject o:trash()){if(Thread.currentThread().isInterrupted())throw new android.os.OperationCanceledException();if(!admin&&locks.locked(o.optString("key")))continue;boolean local=o.optString("type").equals("local");if(local&&!new File(dir,o.optString("backup")).isFile())continue;Uri uri=local?TrashProvider.uri(o.optString("id")):Uri.parse(o.optString("uri"));MediaRepository.Item item=new MediaRepository.Item(uri,o.optString("name"),o.optString("key"),false,(float)o.optDouble("ratio",1));item.accessKey=o.optString("key");item.trashRecord=o;item.mime=o.optString("mime","image/*");item.video=item.mime.startsWith("video/");item.generic=!item.video&&!item.mime.startsWith("image/");item.size=o.optLong("size",local?new File(dir,o.optString("backup")).length():0);item.date=o.optLong("date",o.optLong("time"));item.path=o.optString("path",o.optString("uri"));out.add(item);}return out;}

 synchronized void markExpired(JSONObject o)throws Exception{List<JSONObject> rows=records();for(JSONObject row:rows)if(row.optString("id").equals(o.optString("id")))row.put("type","expired");save(rows);}
 static JSONObject item(MediaRepository.Item i)throws Exception{return new JSONObject().put("uri",i.uri.toString()).put("name",i.name).put("key",i.key).put("mime",i.mime).put("document",i.document).put("video",i.video).put("size",i.size).put("date",i.date).put("ratio",i.ratio).put("path",i.path);}
 static MediaRepository.Item item(JSONObject o){MediaRepository.Item i=new MediaRepository.Item(Uri.parse(o.optString("uri")),o.optString("name"),o.optString("key"),false,(float)o.optDouble("ratio",1));i.date=o.optLong("date");i.path=o.optString("path");i.mime=o.optString("mime");i.document=o.optBoolean("document");i.video=o.optBoolean("video");i.size=o.optLong("size");return i;}
 String digest(Uri u)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=c.getContentResolver().openInputStream(u)){if(in==null)throw new IOException("File unavailable");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static void transfer(InputStream in,OutputStream out)throws IOException{byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
}

